PREFIX bsbm: <http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/vocabulary/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?product ?productLabel ?productId (AVG(?r1) AS ?avgRating1) (AVG(?r2) AS ?avgRating2) (AVG(?r3) AS ?avgRating3) (AVG(?r4) AS ?avgRating4)
WHERE {
  ?review bsbm:reviewFor ?product .
  ?review bsbm:rating1 ?r1 ;
         bsbm:rating2 ?r2 ;
         bsbm:rating3 ?r3 ;
         bsbm:rating4 ?r4 .

  ?product rdfs:label ?productLabel .
  ?product bsbm:productId ?productId .
}
GROUP BY ?product ?productLabel ?productId
ORDER BY DESC(?avgRating1) DESC(?avgRating2) DESC(?avgRating3) DESC(?avgRating4)
LIMIT 10

